def _load_signatures():
    global _SIGS
    if _SIGS is not None:
        return _SIGS
    sigs = []
    if os.path.isdir(_INTEL):
        for d in glob.glob(os.path.join(_INTEL, "*", "signature.npz")):
            try:
                z = np.load(d)
                sigs.append({"slug": os.path.basename(os.path.dirname(d)), "dir": os.path.dirname(d),
                             "med": z["med"].astype(np.float32), "std": z["std"].astype(np.float32),
                             "template_frac": float(z["template_frac"])})
            except Exception:
                pass
    _SIGS = sigs
    return sigs


def _luma64(tex):
    a = np.asarray(tex)
    if a.dtype != np.uint8:
        a = np.clip(a[:, :, :3], 0, 1) * 255.0
    a = a[:, :, :3].astype(np.float32)
    if cv2 is not None:
        g = cv2.cvtColor(a.astype(np.uint8), cv2.COLOR_RGB2GRAY).astype(np.float32)
        g = cv2.resize(g, (64, 64), interpolation=cv2.INTER_AREA)
    else:
        g = a.mean(2)
        g = np.asarray(__import__("PIL.Image", fromlist=["Image"]).fromarray(g.astype(np.uint8)).resize((64, 64)), np.float32)
    return g


def _zncc(a, b):
    """Zero-normalized cross-correlation (color/brightness-invariant structural match)."""
    a = a - a.mean(); b = b - b.mean()
    d = (np.sqrt((a * a).sum()) * np.sqrt((b * b).sum()))
    return float((a * b).sum() / d) if d > 1e-6 else 0.0


def _edges(g):
    """Sobel gradient magnitude — captures the UV PANEL LAYOUT (colour-independent), which is the
    same for every livery of a car. The median's edges = the panel boundaries painters all keep."""
    if cv2 is None:
        return g
    gx = cv2.Sobel(g.astype(np.float32), cv2.CV_32F, 1, 0, ksize=3)
    gy = cv2.Sobel(g.astype(np.float32), cv2.CV_32F, 0, 1, ksize=3)
    return np.sqrt(gx * gx + gy * gy)


def _family(slug):
    s = (slug or "").lower()
    if s.startswith("dirtlatemodel") or s.startswith("superlatemodel"):
        return "dirt_late_model"
    if s.startswith("stockcars"):
        return "nascar_stockcar"
    if s.startswith(("dirtmodified", "dirtumpmod", "skmodified")):
        return "dirt_modified"
    if s.startswith(("dirtsprint", "dirtmidget", "dirtmicro", "silvercrown", "dirtministock", "dirtstreet")):
        return "dirt_open_wheel"
    if s.startswith("dirt"):
        return "dirt_other"
    if "gt3" in s or "gt4" in s or "gte" in s or "gtp" in s or "gt2" in s:
        return "gt_road"
    if s.startswith(("formula", "dallara", "formulair", "formulavee", "rt2000", "usf")) or "indy" in s:
        return "open_wheel"
    if s.startswith(("latemodel", "streetstock", "legends", "ministock")):
        return "late_model"
    if s.startswith(("trucks", "protrucks")):
        return "truck"
    if "cup" in s or "porsche911cup" in s or "porsche992cup" in s or "mx5" in s:
        return "cup_road"
    return "other"


def _norm_slug(s):
    import re
    return re.sub(r"_+", "_", re.sub(r"[^a-z0-9]+", "_", str(s or "").lower())).strip("_")


def folder_slug_from_path(path):
    """Normalized iRacing paint-folder slug for route-time safety checks."""
    if not path:
        return None
    try:
        raw = str(path).strip().rstrip("\\/")
        base = os.path.basename(raw)
        # Smart TGA callers may pass either the paint TGA path or the selected
        # iRacing car folder. Treat extension-bearing paths as files; otherwise
        # the basename is the folder slug.
        if os.path.splitext(base)[1]:
            base = os.path.basename(os.path.dirname(raw))
        return _norm_slug(base)
    except Exception:
        return None


def _vehicle_make_tokens(slug):
    s = _norm_slug(slug)
    groups = {
        "acura": ("acura",),
        "astonmartin": ("astonmartin",),
        "audi": ("audi",),
        "bmw": ("bmw",),
        "cadillac": ("cadillac",),
        "chevy": ("chevy", "camaro", "camarozl", "montecarlo", "impala", "corvette", "vette", "c8r"),
        "dallara": ("dallara",),
        "ferrari": ("ferrari",),
        "ford": ("ford", "mustang", "fusion", "taurus", "thunderbird", "f150"),
        "honda": ("honda",),
        "hyundai": ("hyundai",),
        "lamborghini": ("lamborghini",),
        "ligier": ("ligier",),
        "mazda": ("mazda",),
        "mclaren": ("mclaren",),
        "mercedes": ("mercedes", "amg"),
        "nissan": ("nissan",),
        "porsche": ("porsche",),
        "radical": ("radical",),
        "toyota": ("toyota", "camry", "supra", "tundra", "corolla"),
        "pontiac": ("pontiac", "grandprix"),
        "buick": ("buick", "lesabre"),
    }
    found = set()
    for make, tokens in groups.items():
        if any(tok in s for tok in tokens):
            found.add(make)
    return found


def template_brand_compatible(source_slug, matched_slug):
    """False when a source folder advertises one make but an inferred template is another.

    This intentionally protects only obvious make conflicts. If either side has
    no make token, the older confidence/template-size guards decide.
    """
    source_makes = _vehicle_make_tokens(source_slug)
    matched_makes = _vehicle_make_tokens(matched_slug)
    return not source_makes or not matched_makes or bool(source_makes & matched_makes)


def hint_from_path(path):
    """Best-effort iRacing paint-folder hint for Smart TGA uploads.

    The UI usually sends a canvas PNG, but it can also send the original loaded
    paint path. Exact learned-folder matches become a car slug; otherwise the
    folder name is converted to a safe family hint so car-ID does not wander
    into unrelated templates.
    """
    if not path:
        return None, None
    try:
        slug = folder_slug_from_path(path)
        known = {s["slug"] for s in _load_signatures()}
        if slug in known:
            return slug, _family(slug)
        # iRacing keeps some legacy folders whose learned intel exists only under
        # the newer template slug. Keep aliases narrow: a wrong template is worse
        # than an empty template, so only map proven same-family names.
        aliases = {
            "audir8gt3": "audir8lmsevo2gt3",
            "dirtlatemodel_438": "dirtlatemodel_358",
            "ferrari488gte": "ferrari488gt3",
            "mercedesamggt3": "mercedesamgevogt3",
            "stockcars_chevycamarozl12022": "stockcars_camarozl12018",
            "stockcars_toyotacamry": "stockcars2_camry2015",
            "stockcars2_chevy_cot": "stockcars2_chevy_gen4cup",
            "streetstock_streetstock3": "streetstock_streetstock2",
            "trucks_silverado": "trucks_silverado2019",
        }
        alias = aliases.get(slug)
        if alias in known:
            return alias, _family(alias)
        fam = _family(slug)
        return None, None if fam == "other" else fam
    except Exception:
        return None, None


def identify_car(tex, topk=5, family_hint=None):
    """Return [{slug, family, score, template_frac}] best car-model matches. Score blends a luma match
    with an EDGE/structure match (panel layout) of the livery to each car's learned consensus."""
    sigs = _load_signatures()
    if not sigs:
        return []
    q = _luma64(tex)
    qe = _edges(q)
    scored = []
    filtered = [s for s in sigs if not family_hint or _family(s["slug"]) == family_hint]
    if not filtered:
        filtered = sigs
    for s in filtered:
        m = s["med"]
        score = 0.45 * _zncc(q, m) + 0.55 * _zncc(qe, _edges(m))
        scored.append({"slug": s["slug"], "family": _family(s["slug"]),
                       "score": round(score, 4), "template_frac": s["template_frac"]})
    scored.sort(key=lambda x: -x["score"])
    return scored[:topk]


def _template_prior(slug, H, W):
    """The car's learned GLASS/GRILL/LIGHT/reserved UV regions: LOW-VARIANCE across this car's
    liveries AND consistently template-coloured in the CONSENSUS median. The colour of THIS livery
    never enters -> it can't grab green/dark PAINT (the 2026-06-26 layer-review failure). Resized
    to (H,W). None if the intel isn't there."""
    if not slug or cv2 is None:
        return None

    d = os.path.join(_INTEL, slug)
    tp = os.path.join(d, "template_mask.png"); mp = os.path.join(d, "median.png")
    if not (os.path.isfile(tp) and os.path.isfile(mp)):
        return None
    try:
        m = cv2.imread(tp, cv2.IMREAD_GRAYSCALE)
        med = cv2.imread(mp, cv2.IMREAD_COLOR)  # BGR
        if m is None or med is None:
            return None
        med_r = cv2.resize(med, (W, H), interpolation=cv2.INTER_AREA)
        lowvar = cv2.resize(m, (W, H), interpolation=cv2.INTER_NEAREST) > 127
        hsv = cv2.cvtColor(med_r, cv2.COLOR_BGR2HSV)
        # Fixed car bits are not only dark glass/grilles. NASCAR/ARCA front clips also carry bright
        # headlights/chrome/light bars that CLIP otherwise mistakes for sponsor logos once logos merge
        # into Sponsors by default. The low-variance median mask remains the safety rail: variable
        # white sponsor decals are not stable across the car stack, so they do not pass this gate.
        med_dark = (hsv[:, :, 2] < 72) & (hsv[:, :, 1] < 85)
        med_light = (hsv[:, :, 2] > 168) & (hsv[:, :, 1] < 95)
        template_tone = med_dark | med_light
        # SMOOTHNESS gate (2026-06-27 per-family template depth): GLASS/grills/lights are FLAT in the
        # consensus median; textured paint is not. Requiring low Laplacian sharpens the prior to real
        # car fixtures and avoids the old dark-paint flood.
        gray = cv2.cvtColor(med_r, cv2.COLOR_BGR2GRAY)
        lap = np.abs(cv2.Laplacian(gray, cv2.CV_32F, ksize=3))
        flat = cv2.blur((lap < 8).astype(np.float32), (7, 7)) > 0.6
        return lowvar & template_tone & flat
    except Exception:
        return None


def _sponsor_fragment_supplement(rgb, numbers, sponsors, template, brand):
    """Recover compact sponsor/wordmark fragments that OCR/SAM left in Paint.

    This is intentionally conservative: candidates must be small, high-edge,
    wordmark-like residual islands near an already detected sponsor/logo anchor.
    It exists for bloomq0-style partial sponsor captures, not broad livery art.
    """
    info = {"status": "skipped", "reason": "disabled"}
    if not _SPONSOR_FRAGMENT_SUPPLEMENT:
        return np.zeros(rgb.shape[:2], np.uint8), info
    if cv2 is None:
        return np.zeros(rgb.shape[:2], np.uint8), {"status": "skipped", "reason": "cv2_unavailable"}

    H, W = rgb.shape[:2]
    numbers_b = numbers > 0
    sponsors_b = sponsors > 0
    template_b = template > 0
    brand_b = brand > 0
    anchor_src = sponsors_b | brand_b
    if not anchor_src.any():
        return np.zeros((H, W), np.uint8), {"status": "skipped", "reason": "no_sponsor_anchor"}

    claimed = numbers_b | sponsors_b | template_b | brand_b
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
    edges = cv2.Canny(gray, 45, 120)
    hue = hsv[:, :, 0]
    sat = hsv[:, :, 1]
    val = hsv[:, :, 2]
    canvas_area = float(max(1, H * W))

    number_containment_boxes = []
    number_near = None
    if _SPONSOR_FRAGMENT_NUMBER_CONTAINMENT_VETO and numbers_b.any():
        min_dim = float(max(1, min(H, W)))
        n_count, n_labels, n_stats, _n_cent = cv2.connectedComponentsWithStats(numbers_b.astype(np.uint8), 8)
        for j in range(1, n_count):
            nx, ny, nw, nh, n_area = [int(v) for v in n_stats[j]]
            n_area_frac = n_area / canvas_area
            if (
                n_area_frac >= 0.003
                and max(nw, nh) / min_dim >= 0.055
                and min(nw, nh) / min_dim >= 0.035
            ):
                number_containment_boxes.append({
                    "id": int(j),
                    "bbox": [nx, ny, nw, nh],
                    "area_frac": round(n_area_frac, 6),
                })
        if number_containment_boxes:
            near_radius = max(3, int(round(0.008 * min_dim)))
            near_kernel = cv2.getStructuringElement(
                cv2.MORPH_ELLIPSE, (near_radius * 2 + 1, near_radius * 2 + 1)
            )
            number_near = cv2.dilate(numbers_b.astype(np.uint8), near_kernel) > 0

    visible = ((val > 54) | ((val > 38) & (sat > 42)) | ((edges > 0) & (val > 32))) & ~claimed
    visible = cv2.morphologyEx(visible.astype(np.uint8) * 255, cv2.MORPH_CLOSE, np.ones((2, 2), np.uint8)) > 0

    radius = max(8, int(round(_SPONSOR_FRAGMENT_ANCHOR_RADIUS * min(H, W))))
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (radius * 2 + 1, radius * 2 + 1))
    anchor = cv2.dilate(anchor_src.astype(np.uint8), kernel) > 0

    count, labels, stats, _cent = cv2.connectedComponentsWithStats(visible.astype(np.uint8), 8)
    candidates = []
    vetoed_number_contained = []
    min_area = max(8, int(round(0.000006 * canvas_area)))
    for i in range(1, count):
        x, y, w, h, area = [int(v) for v in stats[i]]
        if area < min_area:
            continue
        if w < 3 or h < 3:
            continue
        comp = labels == i
        area_frac = area / canvas_area
        bbox_area = max(1, w * h)
        bbox_frac = bbox_area / canvas_area
        aspect = max(w / float(max(1, h)), h / float(max(1, w)))
        fill = area / float(bbox_area)
        edge_density = float((edges[comp] > 0).mean()) if area else 0.0
        anchor_overlap = float((comp & anchor).sum()) / float(max(1, area))

        if anchor_overlap <= 0.02:
            continue
        if area_frac > _SPONSOR_FRAGMENT_MAX_AREA or bbox_frac > _SPONSOR_FRAGMENT_MAX_BBOX:
            continue
        if max(w, h) / float(max(1, min(H, W))) > _SPONSOR_FRAGMENT_MAX_DIM:
            continue
        if min(w, h) / float(max(1, min(H, W))) > 0.085 and aspect < 1.8:
            continue
        if not (aspect >= 1.75 or area_frac <= 0.00030 or edge_density >= 0.24):
            continue
        if edge_density < 0.11 and area_frac > 0.00008:
            continue
        if fill > 0.90 and area_frac > 0.00008:
            continue

        comp_hue = hue[comp]
        comp_sat = sat[comp]
        comp_val = val[comp]
        red_or_orange = (
            (comp_hue <= 14) | (comp_hue >= 170) | ((comp_hue >= 15) & (comp_hue <= 28))
        ) & (comp_sat > 80) & (comp_val > 55)
        red_frac = float(red_or_orange.mean()) if area else 0.0
        white_frac = float(((comp_sat < 45) & (comp_val > 145)).mean()) if area else 0.0
        if red_frac > 0.65 and white_frac < 0.15 and area_frac < 0.00010:
            continue
        if red_frac > 0.55 and white_frac < 0.20 and area_frac > 0.00028 and aspect > 1.4 and edge_density < 0.32:
            continue

        veto_box = None
        bbox_overlap_frac = 0.0
        near_number_frac = 0.0
        if number_containment_boxes:
            pad = max(2, int(round(0.006 * min(H, W))))
            for box in number_containment_boxes:
                bx, by, bw, bh = box["bbox"]
                if not (
                    x >= bx - pad
                    and y >= by - pad
                    and x + w <= bx + bw + pad
                    and y + h <= by + bh + pad
                ):
                    continue
                ix0 = max(x, bx)
                iy0 = max(y, by)
                ix1 = min(x + w, bx + bw)
                iy1 = min(y + h, by + bh)
                overlap_area = max(0, ix1 - ix0) * max(0, iy1 - iy0)
                bbox_overlap_frac = overlap_area / float(max(1, w * h))
                if bbox_overlap_frac < 0.92:
                    continue
                if number_near is not None:
                    near_number_frac = float((comp & number_near).sum()) / float(max(1, area))
                if (
                    area_frac <= 0.00036
                    and red_frac >= 0.62
                    and white_frac <= 0.18
                    and edge_density >= 0.18
                    and aspect <= 2.45
                    and near_number_frac >= 0.18
                ):
                    veto_box = box
                    break
        if veto_box is not None:
            vetoed_number_contained.append({
                "id": i,
                "area": area,
                "bbox": [x, y, w, h],
                "area_frac": round(area_frac, 6),
                "aspect": round(aspect, 3),
                "edge_density": round(edge_density, 3),
                "anchor_overlap": round(anchor_overlap, 3),
                "red_frac": round(red_frac, 3),
                "white_frac": round(white_frac, 3),
                "near_number_frac": round(near_number_frac, 3),
                "bbox_overlap_frac": round(bbox_overlap_frac, 3),
                "number_bbox": veto_box["bbox"],
                "number_id": veto_box["id"],
                "reason": "number_contained_warm_sponsor_fragment",
            })
            continue

        score = (anchor_overlap * 2.0 + edge_density) * float(area)
        candidates.append({
            "id": i,
            "score": score,
            "area": area,
            "bbox": [x, y, w, h],
            "area_frac": round(area_frac, 6),
            "aspect": round(aspect, 3),
            "edge_density": round(edge_density, 3),
            "anchor_overlap": round(anchor_overlap, 3),
            "red_frac": round(red_frac, 3),
            "white_frac": round(white_frac, 3),
        })

    candidates.sort(key=lambda item: item["score"], reverse=True)
    cap_pixels = max(1, int(round(_SPONSOR_FRAGMENT_MAX_ADD * canvas_area)))
    out = np.zeros((H, W), bool)
    accepted = []
    used = 0
    capped = False
    for cand in candidates:
        area = int(cand["area"])
        if used + area > cap_pixels:
            capped = True
            continue
        out |= labels == cand["id"]
        accepted.append(cand)
        used += area

    added_frac = float(out.mean())
    return out.astype(np.uint8) * 255, {
        "status": "applied" if accepted else "empty",
        "added_frac": round(added_frac, 6),
        "component_count": len(accepted),
        "candidate_count": len(candidates),
        "capped": capped,
        "max_add": round(float(_SPONSOR_FRAGMENT_MAX_ADD), 6),
        "anchor_radius_px": radius,
        "components": [{k: v for k, v in item.items() if k != "score"} for item in accepted[:8]],
        "vetoed_number_contained_count": len(vetoed_number_contained),
        "vetoed_number_contained": vetoed_number_contained[:8],
    }


def _isolated_wordmark_supplement(rgb, numbers, sponsors, template, brand):
    """Recover isolated wordmarks on dark paint.

    bloomq0 exposed a different miss than the small sponsor-fragment case:
    disconnected bottom wordmarks were left in Paint because they had no nearby
    sponsor anchor. Keep this deliberately narrow so black livery swooshes and
    colored paint striping stay in Paint. Cycle 287 adds sibling-gated warm
    word segments for real dark-body sponsor text that has no sponsor anchor.
    """
    info = {"status": "skipped", "reason": "disabled"}
    if not _ISOLATED_WORDMARK_SUPPLEMENT:
        return np.zeros(rgb.shape[:2], np.uint8), info
    if cv2 is None:
        return np.zeros(rgb.shape[:2], np.uint8), {"status": "skipped", "reason": "cv2_unavailable"}

    H, W = rgb.shape[:2]
    numbers_b = numbers > 0
    sponsors_b = sponsors > 0
    template_b = template > 0
    brand_b = brand > 0
    if not (numbers_b.any() or sponsors_b.any() or brand_b.any()):
        return np.zeros((H, W), np.uint8), {"status": "skipped", "reason": "no_primary_layers"}

    claimed = numbers_b | sponsors_b | template_b | brand_b
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
    edges = cv2.Canny(gray, 45, 120)
    hue = hsv[:, :, 0]
    sat = hsv[:, :, 1]
    val = hsv[:, :, 2]

    visible = (
        (val > 100)
        | ((sat > 60) & (val > 70))
        | ((edges > 0) & (val > 68))
    ) & ~claimed
    visible = cv2.morphologyEx(
        visible.astype(np.uint8) * 255, cv2.MORPH_CLOSE, np.ones((7, 3), np.uint8)
    ) > 0
    visible = cv2.morphologyEx(
        visible.astype(np.uint8) * 255, cv2.MORPH_OPEN, np.ones((2, 2), np.uint8)
    ) > 0

    count, labels, stats, _cent = cv2.connectedComponentsWithStats(visible.astype(np.uint8), 8)
    canvas_area = float(max(1, H * W))
    min_dim = float(max(1, min(H, W)))
    min_area = max(900, int(round(_ISOLATED_WORDMARK_MIN_AREA * canvas_area)))
    min_w = max(48, int(round(0.068 * min_dim)))
    min_h = max(8, int(round(0.012 * min_dim)))
    margin = max(6, int(round(0.010 * min_dim)))
    warm_min_area = max(420, int(round(0.00036 * canvas_area)))
    warm_min_w = max(42, int(round(0.040 * min_dim)))
    warm_min_h = max(15, int(round(0.014 * min_dim)))
    number_radius = max(6, int(round(0.020 * min_dim)))
    number_kernel = cv2.getStructuringElement(
        cv2.MORPH_ELLIPSE, (number_radius * 2 + 1, number_radius * 2 + 1)
    )
    number_anchor = cv2.dilate(numbers_b.astype(np.uint8), number_kernel) > 0
    candidates = []
    warm_segments = []

    for i in range(1, count):
        x, y, w, h, area = [int(v) for v in stats[i]]
        if area < min(min_area, warm_min_area) or w < min(min_w, warm_min_w) or h < min(min_h, warm_min_h):
            continue
        comp = labels == i
        area_frac = area / canvas_area
        bbox_area = max(1, w * h)
        bbox_frac = bbox_area / canvas_area
        aspect = w / float(max(1, h))
        fill = area / float(bbox_area)
        edge_density = float((edges[comp] > 0).mean()) if area else 0.0

        comp_hue = hue[comp]
        comp_sat = sat[comp]
        comp_val = val[comp]
        white_frac = float(((comp_sat < 55) & (comp_val > 135)).mean()) if area else 0.0
        bright_frac = float((comp_val > 130).mean()) if area else 0.0
        red_frac = float((
            ((comp_hue <= 14) | (comp_hue >= 170) | ((comp_hue >= 15) & (comp_hue <= 28)))
            & (comp_sat > 80) & (comp_val > 55)
        ).mean()) if area else 0.0
        yellow_frac = float((
            ((comp_hue >= 16) & (comp_hue <= 42)) & (comp_sat > 70) & (comp_val > 55)
        ).mean()) if area else 0.0
        sat_frac = float(((comp_sat > 80) & (comp_val > 55)).mean()) if area else 0.0
        dark_frac = float((comp_val < 78).mean()) if area else 0.0
        number_overlap = float(number_anchor[comp].mean()) if area else 0.0

        x0 = max(0, x - margin)
        y0 = max(0, y - margin)
        x1 = min(W, x + w + margin)
        y1 = min(H, y + h + margin)
        ring = np.zeros((H, W), bool)
        ring[y0:y1, x0:x1] = True
        ring[y:y + h, x:x + w] = False
        ring_count = float(max(1, ring.sum()))
        dark_bg = float(((val < 80) & ring).sum()) / ring_count
        bright_bg = float(((val > 130) & ring).sum()) / ring_count

        warm_word_segment = (
            area >= warm_min_area
            and warm_min_w <= w <= max(82, int(round(0.080 * min_dim)))
            and warm_min_h <= h <= max(26, int(round(0.026 * min_dim)))
            and 2.2 <= aspect <= 3.7
            and 0.42 <= fill <= 0.72
            and edge_density >= 0.26
            and dark_bg >= 0.70
            and bright_bg <= 0.20
            and white_frac <= 0.08
            and 0.48 <= sat_frac <= 0.78
            and (red_frac >= 0.38 or yellow_frac >= 0.34)
            and dark_frac >= 0.30
            and number_overlap <= 0.05
        )
        if warm_word_segment:
            score = float(area) * (edge_density + sat_frac + dark_bg)
            warm_segments.append({
                "id": i,
                "score": score,
                "area": area,
                "bbox": [x, y, w, h],
                "area_frac": round(area_frac, 6),
                "bbox_frac": round(bbox_frac, 6),
                "aspect": round(aspect, 3),
                "edge_density": round(edge_density, 3),
                "white_frac": round(white_frac, 3),
                "red_frac": round(red_frac, 3),
                "yellow_frac": round(yellow_frac, 3),
                "sat_frac": round(sat_frac, 3),
                "dark_frac": round(dark_frac, 3),
                "dark_bg": round(dark_bg, 3),
                "bright_bg": round(bright_bg, 3),
                "fill": round(fill, 3),
                "number_overlap": round(number_overlap, 3),
                "reason": "warm_dark_wordmark_segment",
                "center_y": y + h / 2.0,
                "height": h,
                "x": x,
                "x2": x + w,
            })

        if area < min_area or w < min_w or h < min_h:
            continue
        if area_frac > _ISOLATED_WORDMARK_MAX_AREA or bbox_frac > _ISOLATED_WORDMARK_MAX_BBOX:
            continue
        if max(w, h) / min_dim > _ISOLATED_WORDMARK_MAX_DIM:
            continue
        if aspect < 3.0:
            continue
        if white_frac < 0.55:
            continue
        if edge_density < 0.16 and not (edge_density >= 0.135 and white_frac >= 0.70 and dark_bg >= 0.86):
            continue
        if red_frac > 0.22 and white_frac < 0.70:
            continue
        if dark_bg < 0.70:
            continue
        if fill > 0.88 and bright_frac < 0.70:
            continue

        score = float(area) * (white_frac + edge_density + dark_bg)
        candidates.append({
            "id": i,
            "score": score,
            "area": area,
            "bbox": [x, y, w, h],
            "area_frac": round(area_frac, 6),
            "bbox_frac": round(bbox_frac, 6),
            "aspect": round(aspect, 3),
            "edge_density": round(edge_density, 3),
            "white_frac": round(white_frac, 3),
            "red_frac": round(red_frac, 3),
            "dark_bg": round(dark_bg, 3),
            "fill": round(fill, 3),
        })

    paired_warm_ids = set()
    sibling_gap = max(10, int(round(0.010 * min_dim)))
    for cand in warm_segments:
        for other in warm_segments:
            if cand["id"] == other["id"]:
                continue
            gap = max(0, max(cand["x"], other["x"]) - min(cand["x2"], other["x2"]))
            v_delta = abs(cand["center_y"] - other["center_y"]) / float(max(cand["height"], other["height"], 1))
            h_ratio = min(cand["height"], other["height"]) / float(max(cand["height"], other["height"], 1))
            if gap <= sibling_gap and v_delta <= 0.25 and h_ratio >= 0.80:
                paired_warm_ids.add(cand["id"])
                break
    paired_warm_segments = [cand for cand in warm_segments if cand["id"] in paired_warm_ids]
    candidates.extend(paired_warm_segments)
    candidates.sort(key=lambda item: item["score"], reverse=True)
    cap_pixels = max(1, int(round(_ISOLATED_WORDMARK_MAX_ADD * canvas_area)))
    out = np.zeros((H, W), bool)
    accepted = []
    used = 0
    capped = False
    for cand in candidates:
        area = int(cand["area"])
        if used + area > cap_pixels:
            capped = True
            continue
        out |= labels == cand["id"]
        accepted.append(cand)
        used += area

    warm_shadow_components = []
    accepted_warm = [cand for cand in accepted if cand.get("reason") == "warm_dark_wordmark_segment"]
    if len(accepted_warm) >= 2:
        warm_anchor = np.zeros((H, W), bool)
        for cand in accepted_warm:
            warm_anchor |= labels == cand["id"]

        group_map = np.zeros((H, W), np.uint8)
        x_pad = max(8, int(round(0.010 * min_dim)))
        y_pad = max(4, int(round(0.005 * min_dim)))
        for cand in accepted_warm:
            x, y, w, h = [int(v) for v in cand["bbox"]]
            x0 = max(0, x - x_pad)
            y0 = max(0, y - y_pad)
            x1 = min(W, x + w + x_pad)
            y1 = min(H, y + h + y_pad)
            group_map[y0:y1, x0:x1] = 1
        group_count, group_labels, group_stats, _group_cent = cv2.connectedComponentsWithStats(group_map, 8)

        edge_near = cv2.dilate(edges.astype(np.uint8), np.ones((3, 3), np.uint8)) > 0
        shadow_radius = max(4, int(round(0.006 * min_dim)))
        shadow_kernel = cv2.getStructuringElement(
            cv2.MORPH_ELLIPSE, (shadow_radius * 2 + 1, shadow_radius * 2 + 1)
        )
        for group_id in range(1, group_count):
            gx, gy, gw, gh, garea = [int(v) for v in group_stats[group_id]]
            group_region = group_labels == group_id
            group_anchor = warm_anchor & group_region
            if not group_anchor.any():
                continue
            anchor_touch_count, _anchor_labels, _anchor_stats, _anchor_cent = cv2.connectedComponentsWithStats(
                group_anchor.astype(np.uint8), 8
            )
            if anchor_touch_count - 1 < 2:
                continue

            anchor_band = cv2.dilate(group_anchor.astype(np.uint8), shadow_kernel) > 0
            band = np.zeros((H, W), bool)
            y0 = max(0, gy - y_pad)
            y1 = min(H, gy + gh + y_pad)
            x0 = max(0, gx - x_pad)
            x1 = min(W, gx + gw + x_pad)
            band[y0:y1, x0:x1] = True

            shadow_seed = (
                band
                & anchor_band
                & ~claimed
                & ~out
                & (val >= 24)
                & (val <= 140)
                & ((sat >= 18) | edge_near)
            )
            shadow_count, shadow_labels, shadow_stats, _shadow_cent = cv2.connectedComponentsWithStats(
                shadow_seed.astype(np.uint8), 8
            )
            for shadow_id in range(1, shadow_count):
                sx, sy, sw, sh, sarea = [int(v) for v in shadow_stats[shadow_id]]
                if sarea < 10:
                    continue
                if sw > max(24, int(round(0.024 * min_dim))) or sh > max(22, int(round(0.022 * min_dim))):
                    continue
                shadow_comp = shadow_labels == shadow_id
                if float(anchor_band[shadow_comp].mean()) < 0.95:
                    continue
                if float(number_anchor[shadow_comp].mean()) > 0.02:
                    continue
                shadow_sat_frac = float((sat[shadow_comp] >= 35).mean())
                shadow_warm_frac = float((
                    (((hue[shadow_comp] >= 16) & (hue[shadow_comp] <= 45))
                     | (hue[shadow_comp] <= 14)
                     | (hue[shadow_comp] >= 170))
                    & (sat[shadow_comp] >= 35)
                    & (val[shadow_comp] >= 24)
                ).mean())
                # Edge contact alone can pull true dark body paint between letters;
                # keep shadow fill tied to saturated/warm antialias evidence.
                if shadow_sat_frac < 0.18 and shadow_warm_frac < 0.10:
                    continue
                if used + sarea > cap_pixels:
                    capped = True
                    continue
                out |= shadow_comp
                used += sarea
                warm_shadow_components.append({
                    "id": f"shadow-{group_id}-{shadow_id}",
                    "area": sarea,
                    "bbox": [sx, sy, sw, sh],
                    "area_frac": round(sarea / canvas_area, 6),
                    "aspect": round(sw / float(max(1, sh)), 3),
                    "fill": round(sarea / float(max(1, sw * sh)), 3),
                    "edge_density": round(float(edge_near[shadow_comp].mean()), 3),
                    "sat_frac": round(shadow_sat_frac, 3),
                    "warm_frac": round(shadow_warm_frac, 3),
                    "dark_frac": round(float((val[shadow_comp] < 78).mean()), 3),
                    "number_overlap": round(float(number_anchor[shadow_comp].mean()), 3),
                    "reason": "warm_dark_wordmark_shadow_fill",
                })

    accepted.extend(warm_shadow_components)
    added_frac = float(out.mean())
    return out.astype(np.uint8) * 255, {
        "status": "applied" if accepted else "empty",
        "added_frac": round(added_frac, 6),
        "component_count": len(accepted),
        "candidate_count": len(candidates),
        "warm_segment_candidates": len(warm_segments),
        "warm_segment_paired_count": len(paired_warm_segments),
        "warm_shadow_component_count": len(warm_shadow_components),
        "capped": capped,
        "max_add": round(float(_ISOLATED_WORDMARK_MAX_ADD), 6),
        "components": [
            {k: v for k, v in item.items() if k not in {"score", "center_y", "height", "x", "x2"}}
            for item in accepted[:8]
        ],
    }


def _tiny_logotype_residual_supplement(rgb, numbers, sponsors, template, brand):
    """Recover tiny white sponsor/logotype crumbs left in Paint after the broad passes.

    bloomq0 has many little sponsor textlines where OCR/SAM finds only part of the
    wordmark. This guard is intentionally post-pass and dark-background-biased so
    template fixtures, bright body panels, and red/gray livery strokes stay out of
    Sponsors.
    """
    info = {"status": "skipped", "reason": "disabled"}
    if not _TINY_LOGOTYPE_SUPPLEMENT:
        return np.zeros(rgb.shape[:2], np.uint8), info
    if cv2 is None:
        return np.zeros(rgb.shape[:2], np.uint8), {"status": "skipped", "reason": "cv2_unavailable"}

    H, W = rgb.shape[:2]
    numbers_b = numbers > 0
    sponsors_b = sponsors > 0
    template_b = template > 0
    brand_b = brand > 0
    if not (numbers_b.any() or sponsors_b.any() or brand_b.any()):
        return np.zeros((H, W), np.uint8), {"status": "skipped", "reason": "no_primary_layers"}

    claimed = numbers_b | sponsors_b | template_b | brand_b
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
    edges = cv2.Canny(gray, 45, 120)
    hue = hsv[:, :, 0]
    sat = hsv[:, :, 1]
    val = hsv[:, :, 2]

    visible = (
        ((val > 112) & (sat < 120))
        | ((sat > 55) & (val > 80))
        | ((edges > 0) & (val > 70))
    ) & ~claimed
    visible = cv2.morphologyEx(
        visible.astype(np.uint8) * 255, cv2.MORPH_CLOSE, np.ones((3, 3), np.uint8)
    ) > 0
    visible = cv2.morphologyEx(
        visible.astype(np.uint8) * 255, cv2.MORPH_OPEN, np.ones((2, 2), np.uint8)
    ) > 0

    anchor_src = sponsors_b | brand_b
    if anchor_src.any():
        radius = max(6, int(round(_TINY_LOGOTYPE_ANCHOR_RADIUS * min(H, W))))
        kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (radius * 2 + 1, radius * 2 + 1))
        anchor = cv2.dilate(anchor_src.astype(np.uint8), kernel) > 0
    else:
        radius = 0
        anchor = np.zeros((H, W), bool)

    count, labels, stats, _cent = cv2.connectedComponentsWithStats(visible.astype(np.uint8), 8)
    canvas_area = float(max(1, H * W))
    min_dim = float(max(1, min(H, W)))
    min_area = max(12, int(round(0.000017 * canvas_area)))
    min_w = max(5, int(round(0.004 * min_dim)))
    min_h = max(3, int(round(0.003 * min_dim)))
    margin = max(4, int(round(0.008 * min_dim)))
    candidates = []

    for i in range(1, count):
        x, y, w, h, area = [int(v) for v in stats[i]]
        if area < min_area or w < min_w or h < min_h:
            continue
        comp = labels == i
        area_frac = area / canvas_area
        bbox_area = max(1, w * h)
        bbox_frac = bbox_area / canvas_area
        aspect = max(w / float(max(1, h)), h / float(max(1, w)))
        horizontal_aspect = w / float(max(1, h))
        fill = area / float(bbox_area)
        edge_density = float((edges[comp] > 0).mean()) if area else 0.0
        anchor_overlap = float((comp & anchor).sum()) / float(max(1, area))

        comp_hue = hue[comp]
        comp_sat = sat[comp]
        comp_val = val[comp]
        white_frac = float(((comp_sat < 70) & (comp_val > 132)).mean()) if area else 0.0
        sat_frac = float(((comp_sat > 80) & (comp_val > 70)).mean()) if area else 0.0
        red_frac = float((
            ((comp_hue <= 14) | (comp_hue >= 170) | ((comp_hue >= 15) & (comp_hue <= 28)))
            & (comp_sat > 80) & (comp_val > 55)
        ).mean()) if area else 0.0

        x0 = max(0, x - margin)
        y0 = max(0, y - margin)
        x1 = min(W, x + w + margin)
        y1 = min(H, y + h + margin)
        ring = np.zeros((H, W), bool)
        ring[y0:y1, x0:x1] = True
        ring[y:y + h, x:x + w] = False
        dark_bg = float(((val < 84) & ring).sum()) / float(max(1, ring.sum()))

        remote_wordmark = dark_bg >= 0.88 and white_frac >= 0.55 and horizontal_aspect >= 2.3
        anchored_wordmark = anchor_overlap >= 0.18
        text_evidence = (
            white_frac >= 0.42
            or (white_frac >= 0.30 and edge_density >= 0.30 and anchor_overlap >= 0.45 and aspect >= 3.0)
        )

        if area_frac > _TINY_LOGOTYPE_MAX_AREA or bbox_frac > _TINY_LOGOTYPE_MAX_BBOX:
            continue
        if max(w, h) / min_dim > _TINY_LOGOTYPE_MAX_DIM:
            continue
        if dark_bg < 0.78:
            continue
        if not (anchored_wordmark or remote_wordmark):
            continue
        if not text_evidence:
            continue
        if edge_density < 0.12 and not (white_frac >= 0.62 and dark_bg >= 0.88):
            continue
        if red_frac > 0.42 and white_frac < 0.60:
            continue
        if sat_frac > 0.48 and white_frac < 0.55:
            continue
        if fill < 0.045 or fill > 0.94:
            continue
        if aspect > 12.0 and area < 90:
            continue

        score = float(area) * (white_frac + edge_density + dark_bg + anchor_overlap * 0.35)
        candidates.append({
            "id": i,
            "score": score,
            "area": area,
            "bbox": [x, y, w, h],
            "area_frac": round(area_frac, 6),
            "bbox_frac": round(bbox_frac, 6),
            "aspect": round(aspect, 3),
            "edge_density": round(edge_density, 3),
            "white_frac": round(white_frac, 3),
            "red_frac": round(red_frac, 3),
            "sat_frac": round(sat_frac, 3),
            "dark_bg": round(dark_bg, 3),
            "anchor_overlap": round(anchor_overlap, 3),
            "fill": round(fill, 3),
        })

    candidates.sort(key=lambda item: item["score"], reverse=True)
    cap_pixels = max(1, int(round(_TINY_LOGOTYPE_MAX_ADD * canvas_area)))
    out = np.zeros((H, W), bool)
    accepted = []
    used = 0
    capped = False
    for cand in candidates:
        area = int(cand["area"])
        if used + area > cap_pixels:
            capped = True
            continue
        out |= labels == cand["id"]
        accepted.append(cand)
        used += area

    added_frac = float(out.mean())
    return out.astype(np.uint8) * 255, {
        "status": "applied" if accepted else "empty",
        "added_frac": round(added_frac, 6),
        "component_count": len(accepted),
        "candidate_count": len(candidates),
        "capped": capped,
        "max_add": round(float(_TINY_LOGOTYPE_MAX_ADD), 6),
        "anchor_radius_px": radius,
        "components": [{k: v for k, v in item.items() if k != "score"} for item in accepted[:12]],
    }


def _micro_logotype_residual_supplement(rgb, numbers, sponsors, template, brand):
    """Recover final sponsor-letter crumbs left after the normal tiny-logotype pass.

    This is intentionally much smaller than the prior sponsor supplements. It only
    touches high-edge white/gray residuals embedded in an existing sponsor/logo
    neighborhood, so it can repair partial letters without sweeping livery strokes.
    """
    info = {"status": "skipped", "reason": "disabled"}
    if not _MICRO_LOGOTYPE_SUPPLEMENT:
        return np.zeros(rgb.shape[:2], np.uint8), info
    if cv2 is None:
        return np.zeros(rgb.shape[:2], np.uint8), {"status": "skipped", "reason": "cv2_unavailable"}

    H, W = rgb.shape[:2]
    numbers_b = numbers > 0
    sponsors_b = sponsors > 0
    template_b = template > 0
    brand_b = brand > 0
    anchor_src = sponsors_b | brand_b
    if not anchor_src.any():
        return np.zeros((H, W), np.uint8), {"status": "skipped", "reason": "no_sponsor_anchor"}

    claimed = numbers_b | sponsors_b | template_b | brand_b
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
    edges = cv2.Canny(gray, 45, 120)
    hue = hsv[:, :, 0]
    sat = hsv[:, :, 1]
    val = hsv[:, :, 2]

    visible = (((val > 104) & (sat < 135)) | (edges > 0)) & ~claimed
    visible = cv2.morphologyEx(
        visible.astype(np.uint8) * 255, cv2.MORPH_CLOSE, np.ones((2, 2), np.uint8)
    ) > 0

    min_dim = float(max(1, min(H, W)))
    radius = max(6, int(round(_MICRO_LOGOTYPE_ANCHOR_RADIUS * min_dim)))
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (radius * 2 + 1, radius * 2 + 1))
    anchor = cv2.dilate(anchor_src.astype(np.uint8), kernel) > 0

    count, labels, stats, _cent = cv2.connectedComponentsWithStats(visible.astype(np.uint8), 8)
    canvas_area = float(max(1, H * W))
    border = max(18, int(round(0.018 * min_dim)))
    margin = max(3, int(round(0.006 * min_dim)))
    broad = []
    thin = []
    dark = []

    for i in range(1, count):
        x, y, w, h, area = [int(v) for v in stats[i]]
        if area < 8:
            continue
        comp = labels == i
        bbox_area = max(1, w * h)
        bbox_frac = bbox_area / canvas_area
        fill = area / float(bbox_area)
        edge_density = float((edges[comp] > 0).mean()) if area else 0.0
        anchor_overlap = float((comp & anchor).sum()) / float(max(1, area))

        comp_hue = hue[comp]
        comp_sat = sat[comp]
        comp_val = val[comp]
        white_frac = float(((comp_sat < 80) & (comp_val > 122)).mean()) if area else 0.0
        sat_frac = float(((comp_sat > 95) & (comp_val > 70)).mean()) if area else 0.0
        red_frac = float((
            ((comp_hue <= 14) | (comp_hue >= 170) | ((comp_hue >= 15) & (comp_hue <= 28)))
            & (comp_sat > 80) & (comp_val > 55)
        ).mean()) if area else 0.0

        x0 = max(0, x - margin)
        y0 = max(0, y - margin)
        x1 = min(W, x + w + margin)
        y1 = min(H, y + h + margin)
        ring = np.zeros((H, W), bool)
        ring[y0:y1, x0:x1] = True
        ring[y:y + h, x:x + w] = False
        dark_bg = float(((val < 96) & ring).sum()) / float(max(1, ring.sum()))

        if anchor_overlap < 0.90 or dark_bg < 0.55:
            continue
        if red_frac > 0.12 or sat_frac > 0.35:
            continue
        if edge_density < 0.18 or fill < 0.10:
            continue

        base = {
            "id": i,
            "area": area,
            "bbox": [x, y, w, h],
            "area_frac": round(area / canvas_area, 6),
            "bbox_frac": round(bbox_frac, 6),
            "edge_density": round(edge_density, 3),
            "white_frac": round(white_frac, 3),
            "red_frac": round(red_frac, 3),
            "sat_frac": round(sat_frac, 3),
            "dark_bg": round(dark_bg, 3),
            "anchor_overlap": round(anchor_overlap, 3),
            "fill": round(fill, 3),
        }
        score = float(area) * (white_frac + edge_density + dark_bg + anchor_overlap * 0.4)
        if (
            area <= 350
            and max(w, h) <= 84
            and bbox_frac <= 0.00145
            and fill <= 0.97
            and (white_frac >= 0.30 or (white_frac >= 0.24 and edge_density >= 0.38))
        ):
            item = dict(base)
            item["bucket"] = "broad"
            item["score"] = score
            broad.append(item)
        if (
            area <= 45
            and max(w, h) <= 24
            and min(w, h) <= 3
            and white_frac >= 0.28
            and edge_density >= 0.35
            and (border <= x <= W - border)
            and (border <= y <= H - border)
        ):
            item = dict(base)
            item["bucket"] = "thin"
            item["score"] = score + float(area) * 0.25
            thin.append(item)

    # Cycle 552: Some DLM wordmarks recover their pale strokes first, leaving
    # tiny black letter interiors as Paint holes. Detect those separately so the
    # existing pale/edge-tuned connected components above remain stable.
    near_radius = max(2, int(round(0.004 * min_dim)))
    near_kernel = cv2.getStructuringElement(
        cv2.MORPH_ELLIPSE, (near_radius * 2 + 1, near_radius * 2 + 1)
    )
    near_anchor = cv2.dilate(anchor_src.astype(np.uint8), near_kernel) > 0
    dark_visible = (
        (val < 96)
        & (sat < 125)
        & ~claimed
        & near_anchor
    )
    dark_visible = cv2.morphologyEx(
        dark_visible.astype(np.uint8) * 255, cv2.MORPH_CLOSE, np.ones((2, 2), np.uint8)
    ) > 0
    dark_count, dark_labels, dark_stats, _dark_cent = cv2.connectedComponentsWithStats(
        dark_visible.astype(np.uint8), 8
    )
    for i in range(1, dark_count):
        x, y, w, h, area = [int(v) for v in dark_stats[i]]
        if area < 10:
            continue
        comp = dark_labels == i
        bbox_area = max(1, w * h)
        bbox_frac = bbox_area / canvas_area
        fill = area / float(bbox_area)
        edge_density = float((edges[comp] > 0).mean()) if area else 0.0
        anchor_overlap = float((comp & anchor).sum()) / float(max(1, area))

        comp_sat = sat[comp]
        comp_val = val[comp]
        dark_frac = float(((comp_val < 90) & (comp_sat < 130)).mean()) if area else 0.0

        x0 = max(0, x - margin)
        y0 = max(0, y - margin)
        x1 = min(W, x + w + margin)
        y1 = min(H, y + h + margin)
        ring = np.zeros((H, W), bool)
        ring[y0:y1, x0:x1] = True
        ring[y:y + h, x:x + w] = False
        ring_area = float(max(1, ring.sum()))
        bbox = np.zeros((H, W), bool)
        bbox[y:y + h, x:x + w] = True
        bbox_anchor = float((anchor_src & bbox).sum()) / float(max(1, bbox.sum()))
        ring_anchor = float((anchor_src & ring).sum()) / ring_area
        number_bbox = float((numbers_b & bbox).sum()) / float(max(1, bbox.sum()))
        template_bbox = float((template_b & bbox).sum()) / float(max(1, bbox.sum()))
        dark_ring = float(((val < 104) & ring).sum()) / ring_area
        white_context = float(((sat < 85) & (val > 126) & (bbox | ring)).sum()) / float(max(1, (bbox | ring).sum()))

        if (
            area <= 240
            and max(w, h) <= 34
            and min(w, h) <= 24
            and bbox_frac <= 0.00092
            and 0.10 <= fill <= 0.90
            and dark_frac >= 0.62
            and anchor_overlap >= 0.96
            and (bbox_anchor >= 0.08 or ring_anchor >= 0.22)
            and (white_context >= 0.08 or edge_density >= 0.14)
            and (dark_ring >= 0.28 or white_context >= 0.28)
            and number_bbox <= 0.02
            and template_bbox <= 0.02
        ):
            score = float(area) * (
                dark_frac
                + edge_density * 1.5
                + white_context
                + bbox_anchor * 0.6
                + ring_anchor * 0.4
            )
            dark.append({
                "id": i,
                "area": area,
                "bbox": [x, y, w, h],
                "area_frac": round(area / canvas_area, 6),
                "bbox_frac": round(bbox_frac, 6),
                "edge_density": round(edge_density, 3),
                "dark_frac": round(dark_frac, 3),
                "white_context": round(white_context, 3),
                "bbox_anchor": round(bbox_anchor, 3),
                "ring_anchor": round(ring_anchor, 3),
                "dark_ring": round(dark_ring, 3),
                "anchor_overlap": round(anchor_overlap, 3),
                "fill": round(fill, 3),
                "bucket": "dark",
                "score": score,
            })

    broad.sort(key=lambda item: item["score"], reverse=True)
    thin.sort(key=lambda item: item["score"], reverse=True)
    dark.sort(key=lambda item: item["score"], reverse=True)
    total_cap = max(1, int(round(_MICRO_LOGOTYPE_MAX_ADD * canvas_area)))
    caps = [
        (broad, max(1, int(round(_MICRO_LOGOTYPE_BROAD_MAX_ADD * canvas_area)))),
        (thin, max(1, int(round(_MICRO_LOGOTYPE_THIN_MAX_ADD * canvas_area)))),
    ]
    out = np.zeros((H, W), bool)
    accepted = []
    used = 0
    used_ids = set()
    capped = False
    bucket_counts = {"broad": 0, "thin": 0, "dark": 0}
    for pool, bucket_cap in caps:
        bucket_used = 0
        for cand in pool:
            cid = int(cand["id"])
            area = int(cand["area"])
            if cid in used_ids:
                continue
            if bucket_used + area > bucket_cap or used + area > total_cap:
                capped = True
                continue
            out |= labels == cid
            used_ids.add(cid)
            bucket_used += area
            used += area
            bucket_counts[cand["bucket"]] += 1
            accepted.append(cand)

    dark_cap = max(1, int(round(_MICRO_LOGOTYPE_DARK_MAX_ADD * canvas_area)))
    dark_used = 0
    dark_ids = set()
    for cand in dark:
        cid = int(cand["id"])
        area = int(cand["area"])
        if cid in dark_ids:
            continue
        comp = dark_labels == cid
        new = comp & ~out
        new_area = int(new.sum())
        if new_area < max(6, int(round(area * 0.35))):
            continue
        if dark_used + new_area > dark_cap or used + new_area > total_cap:
            capped = True
            continue
        out |= comp
        dark_ids.add(cid)
        dark_used += new_area
        used += new_area
        bucket_counts["dark"] += 1
        accepted.append(cand)

    added_frac = float(out.mean())
    return out.astype(np.uint8) * 255, {
        "status": "applied" if accepted else "empty",
        "added_frac": round(added_frac, 6),
        "component_count": len(accepted),
        "candidate_count": len(broad) + len(thin) + len(dark),
        "broad_candidate_count": len(broad),
        "thin_candidate_count": len(thin),
        "dark_candidate_count": len(dark),
        "bucket_counts": bucket_counts,
        "capped": capped,
        "max_add": round(float(_MICRO_LOGOTYPE_MAX_ADD), 6),
        "broad_max_add": round(float(_MICRO_LOGOTYPE_BROAD_MAX_ADD), 6),
        "thin_max_add": round(float(_MICRO_LOGOTYPE_THIN_MAX_ADD), 6),
        "dark_max_add": round(float(_MICRO_LOGOTYPE_DARK_MAX_ADD), 6),
        "anchor_radius_px": radius,
        "dark_near_anchor_radius_px": near_radius,
        "components": [{k: v for k, v in item.items() if k != "score"} for item in accepted[:10]],
    }


def _colored_micro_logo_residual_supplement(rgb, numbers, sponsors, template, brand):
    """Recover tiny saturated logo/sticker crumbs embedded in Sponsor neighborhoods.

    bshepp1 left a few colored micro-decal pieces in Paint after the pale
    logotype passes. This guard is deliberately smaller and stricter than the
    white/gray micro-logotype recovery: candidates must be tiny, saturated, and
    locally surrounded by existing sponsor pixels.
    """
    info = {"status": "skipped", "reason": "disabled"}
    if not _COLORED_MICRO_LOGO_SUPPLEMENT:
        return np.zeros(rgb.shape[:2], np.uint8), info
    if cv2 is None:
        return np.zeros(rgb.shape[:2], np.uint8), {"status": "skipped", "reason": "cv2_unavailable"}

    H, W = rgb.shape[:2]
    numbers_b = numbers > 0
    sponsors_b = sponsors > 0
    template_b = template > 0
    brand_b = brand > 0
    anchor_src = sponsors_b | brand_b
    if not anchor_src.any():
        return np.zeros((H, W), np.uint8), {"status": "skipped", "reason": "no_sponsor_anchor"}

    claimed = numbers_b | sponsors_b | template_b | brand_b
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
    edges = cv2.Canny(gray, 45, 120)
    hue = hsv[:, :, 0]
    sat = hsv[:, :, 1]
    val = hsv[:, :, 2]

    visible = ((sat > 95) & (val > 70) & ~claimed)
    visible = cv2.morphologyEx(
        visible.astype(np.uint8) * 255, cv2.MORPH_CLOSE, np.ones((2, 2), np.uint8)
    ) > 0

    min_dim = float(max(1, min(H, W)))
    radius = max(5, int(round(_COLORED_MICRO_LOGO_ANCHOR_RADIUS * min_dim)))
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (radius * 2 + 1, radius * 2 + 1))
    anchor = cv2.dilate(anchor_src.astype(np.uint8), kernel) > 0

    count, labels, stats, _cent = cv2.connectedComponentsWithStats(visible.astype(np.uint8), 8)
    canvas_area = float(max(1, H * W))
    margin = max(3, int(round(0.006 * min_dim)))
    candidates = []

    for i in range(1, count):
        x, y, w, h, area = [int(v) for v in stats[i]]
        if area < 18 or area > 360:
            continue
        if x <= 1 or y <= 1 or x + w >= W - 1 or y + h >= H - 1:
            continue
        if w < 4 or h < 3:
            continue
        comp = labels == i
        bbox_area = max(1, w * h)
        area_frac = area / canvas_area
        bbox_frac = bbox_area / canvas_area
        fill = area / float(bbox_area)
        aspect = max(w / float(max(1, h)), h / float(max(1, w)))
        edge_density = float((edges[comp] > 0).mean()) if area else 0.0
        anchor_overlap = float((comp & anchor).sum()) / float(max(1, area))

        x0 = max(0, x - margin)
        y0 = max(0, y - margin)
        x1 = min(W, x + w + margin)
        y1 = min(H, y + h + margin)
        local = np.zeros((H, W), bool)
        local[y0:y1, x0:x1] = True
        near_sponsor = float((local & anchor_src).sum()) / float(max(1, local.sum()))

        comp_hue = hue[comp]
        comp_sat = sat[comp]
        comp_val = val[comp]
        sat_frac = float(((comp_sat > 105) & (comp_val > 70)).mean()) if area else 0.0
        white_frac = float(((comp_sat < 80) & (comp_val > 122)).mean()) if area else 0.0
        red_frac = float((
            ((comp_hue <= 14) | (comp_hue >= 170) | ((comp_hue >= 15) & (comp_hue <= 28)))
            & (comp_sat > 80) & (comp_val > 55)
        ).mean()) if area else 0.0

        if bbox_frac > 0.00042:
            continue
        if max(w, h) / min_dim > 0.042 or min(w, h) / min_dim > 0.018:
            continue
        if fill < 0.45:
            continue
        if sat_frac < 0.55 or white_frac > 0.50:
            continue
        if anchor_overlap < 0.92 or near_sponsor < _COLORED_MICRO_LOGO_NEAR_SPONSOR_MIN:
            continue
        if red_frac > 0.70 and white_frac < 0.12 and edge_density < 0.24:
            continue

        score = float(area) * (near_sponsor * 2.0 + anchor_overlap + edge_density + sat_frac * 0.5)
        candidates.append({
            "id": i,
            "score": score,
            "area": area,
            "bbox": [x, y, w, h],
            "area_frac": round(area_frac, 6),
            "bbox_frac": round(bbox_frac, 6),
            "aspect": round(aspect, 3),
            "fill": round(fill, 3),
            "edge_density": round(edge_density, 3),
            "anchor_overlap": round(anchor_overlap, 3),
            "near_sponsor": round(near_sponsor, 3),
            "sat_frac": round(sat_frac, 3),
            "white_frac": round(white_frac, 3),
            "red_frac": round(red_frac, 3),
        })

    candidates.sort(key=lambda item: item["score"], reverse=True)
    cap_pixels = max(1, int(round(_COLORED_MICRO_LOGO_MAX_ADD * canvas_area)))
    out = np.zeros((H, W), bool)
    accepted = []
    used = 0
    capped = False
    for cand in candidates:
        area = int(cand["area"])
        if used + area > cap_pixels:
            capped = True
            continue
        out |= labels == int(cand["id"])
        accepted.append(cand)
        used += area

    added_frac = float(out.mean())
    return out.astype(np.uint8) * 255, {
        "status": "applied" if accepted else "empty",
        "added_frac": round(added_frac, 6),
        "component_count": len(accepted),
        "candidate_count": len(candidates),
        "capped": capped,
        "max_add": round(float(_COLORED_MICRO_LOGO_MAX_ADD), 6),
        "anchor_radius_px": radius,
        "near_sponsor_min": round(float(_COLORED_MICRO_LOGO_NEAR_SPONSOR_MIN), 6),
        "components": [{k: v for k, v in item.items() if k != "score"} for item in accepted[:10]],
    }


def _bright_panel_micro_logo_residual_supplement(rgb, numbers, sponsors, template, brand):
    """Recover tiny sponsor/logo crumbs stranded on bright sponsor panels.

    1-Francis2001 leaves a few micro logo/text pieces in Paint on white sponsor
    panels. The existing micro-logotype guard is dark-background biased, so keep
    this companion guard bright-panel biased and very small/capped.
    """
    info = {"status": "skipped", "reason": "disabled"}
    if not _BRIGHT_PANEL_MICRO_LOGO_SUPPLEMENT:
        return np.zeros(rgb.shape[:2], np.uint8), info
    if cv2 is None:
        return np.zeros(rgb.shape[:2], np.uint8), {"status": "skipped", "reason": "cv2_unavailable"}

    H, W = rgb.shape[:2]
    numbers_b = numbers > 0
    sponsors_b = sponsors > 0
    template_b = template > 0
    brand_b = brand > 0
    anchor_src = sponsors_b | brand_b
    if not anchor_src.any():
        return np.zeros((H, W), np.uint8), {"status": "skipped", "reason": "no_sponsor_anchor"}

    claimed = numbers_b | sponsors_b | template_b | brand_b
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
    edges = cv2.Canny(gray, 45, 120)
    hue = hsv[:, :, 0]
    sat = hsv[:, :, 1]
    val = hsv[:, :, 2]

    visible = (
        ((val > 118) & (sat < 170))
        | ((sat > 70) & (val > 92))
        | ((edges > 0) & (val > 82))
    ) & ~claimed
    visible = cv2.morphologyEx(
        visible.astype(np.uint8) * 255, cv2.MORPH_CLOSE, np.ones((3, 3), np.uint8)
    ) > 0

    min_dim = float(max(1, min(H, W)))
    radius = max(6, int(round(_BRIGHT_PANEL_MICRO_LOGO_ANCHOR_RADIUS * min_dim)))
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (radius * 2 + 1, radius * 2 + 1))
    anchor = cv2.dilate(anchor_src.astype(np.uint8), kernel) > 0

    count, labels, stats, _cent = cv2.connectedComponentsWithStats(visible.astype(np.uint8), 8)
    canvas_area = float(max(1, H * W))
    margin = max(4, int(round(0.008 * min_dim)))
    candidates = []

    for i in range(1, count):
        x, y, w, h, area = [int(v) for v in stats[i]]
        if area < 10 or area > 190:
            continue
        if x <= 1 or y <= 1 or x + w >= W - 1 or y + h >= H - 1:
            continue
        if max(w, h) > 24 or min(w, h) > 16 or w < 3 or h < 3:
            continue
        comp = labels == i
        bbox_area = max(1, w * h)
        area_frac = area / canvas_area
        bbox_frac = bbox_area / canvas_area
        fill = area / float(bbox_area)
        aspect = max(w / float(max(1, h)), h / float(max(1, w)))
        edge_density = float((edges[comp] > 0).mean()) if area else 0.0
        anchor_overlap = float((comp & anchor).sum()) / float(max(1, area))

        x0 = max(0, x - margin)
        y0 = max(0, y - margin)
        x1 = min(W, x + w + margin)
        y1 = min(H, y + h + margin)
        local = np.zeros((H, W), bool)
        local[y0:y1, x0:x1] = True
        ring = local.copy()
        ring[y:y + h, x:x + w] = False
        near_sponsor = float((local & anchor_src).sum()) / float(max(1, local.sum()))
        bright_bg = float(((val > 145) & (sat < 105) & ring).sum()) / float(max(1, ring.sum()))
        dark_bg = float(((val < 90) & ring).sum()) / float(max(1, ring.sum()))

        comp_hue = hue[comp]
        comp_sat = sat[comp]
        comp_val = val[comp]
        white_frac = float(((comp_sat < 85) & (comp_val > 132)).mean()) if area else 0.0
        sat_frac = float(((comp_sat > 90) & (comp_val > 72)).mean()) if area else 0.0
        red_frac = float((
            ((comp_hue <= 14) | (comp_hue >= 170) | ((comp_hue >= 15) & (comp_hue <= 28)))
            & (comp_sat > 80) & (comp_val > 55)
        ).mean()) if area else 0.0

        if bbox_frac > 0.00038 or area_frac > 0.00019:
            continue
        if fill < 0.18:
            continue
        if anchor_overlap < 0.85:
            continue
        if bright_bg < 0.68 or dark_bg > 0.18:
            continue
        if not (white_frac >= 0.28 or sat_frac >= 0.45 or edge_density >= 0.28):
            continue
        if red_frac > 0.70:
            continue

        score = float(area) * (bright_bg * 1.6 + anchor_overlap + edge_density + white_frac + sat_frac * 0.45)
        candidates.append({
            "id": i,
            "score": score,
            "area": area,
            "bbox": [x, y, w, h],
            "area_frac": round(area_frac, 6),
            "bbox_frac": round(bbox_frac, 6),
            "aspect": round(aspect, 3),
            "fill": round(fill, 3),
            "edge_density": round(edge_density, 3),
            "anchor_overlap": round(anchor_overlap, 3),
            "near_sponsor": round(near_sponsor, 3),
            "bright_bg": round(bright_bg, 3),
            "dark_bg": round(dark_bg, 3),
            "white_frac": round(white_frac, 3),
            "sat_frac": round(sat_frac, 3),
            "red_frac": round(red_frac, 3),
        })

    candidates.sort(key=lambda item: item["score"], reverse=True)
    cap_pixels = max(1, int(round(_BRIGHT_PANEL_MICRO_LOGO_MAX_ADD * canvas_area)))
    out = np.zeros((H, W), bool)
    accepted = []
    used = 0
    capped = False
    for cand in candidates:
        area = int(cand["area"])
        if used + area > cap_pixels:
            capped = True
            continue
        out |= labels == int(cand["id"])
        accepted.append(cand)
        used += area

    added_frac = float(out.mean())
    return out.astype(np.uint8) * 255, {
        "status": "applied" if accepted else "empty",
        "added_frac": round(added_frac, 6),
        "component_count": len(accepted),
        "candidate_count": len(candidates),
        "capped": capped,
        "max_add": round(float(_BRIGHT_PANEL_MICRO_LOGO_MAX_ADD), 6),
        "anchor_radius_px": radius,
        "components": [{k: v for k, v in item.items() if k != "score"} for item in accepted[:10]],
    }


def _panel_text_residual_supplement(rgb, numbers, sponsors, template, brand):
    """Recover compact sponsor/contingency text stranded inside bright decal panels.

    bpierce exposes small readable labels as Paint holes inside already-detected
    number/sponsor panels. 1-MILES1 adds a tiny vertical sponsor glyph on a
    bright/orange logo panel. DudeWipes55 adds a sparse cyan/dark sponsor-logo
    shard embedded in a dark logo badge. 77-Chilis-SPB adds tiny white/dark
    text crumbs embedded in black sponsor strips. 1-WendysCup adds a smooth
    white lens/fill crumb trapped inside a dark sponsor-logo badge. Cycle 278
    adds a UV-border case: sparse saturated panel holes stranded inside an
    existing sponsor neighborhood when a vertical textline is clipped by the
    canvas edge. Cycle 279 adds a larger sponsor-shell case: colored logo-fill
    islands left in Paint after the surrounding false-number sponsor outline was
    demoted. Cycle 283 adds Chubzilla's pale 2px sponsor hairline text stroke,
    but only when it is fully Sponsor-anchored and away from Numbers. Cycle 284
    adds mbag's cool/dark 2px sponsor-logo hairlines as a separate saturated
    family instead of loosening the pale branch. Cycle 285 adds the paired
    compact dark logo-fill centers inside yellow/dark mbag sponsor marks; Cycle
    286 keeps that same family but allows the low end of route-internal
    saturation after resize/compression. Cycle 290 adds a warm/red vertical
    contingency-glyph family for ARCA-style stacked sponsor panels, gated by
    local sponsor dominance so nearby number trim stays put. Cycle 291 adds a
    compact yellow-panel sponsor wordmark family for MENARDS-style sponsor text
    stranded as Paint near number/template context. Cycle 292 adds a tiny
    warm wordmark-crumb family for residual strokes inside already accepted
    warm/dark sponsor text, while requiring zero nearby Number evidence. Cycle
    324 adds tiny blue/white sponsor-panel logo crumbs seen on real Silverado
    truck panels, gated by blue panel context and zero Number evidence. Cycle
    325 adds the mixed-mask sibling: the remaining Paint pixels of a tiny blue
    sponsor glyph when most of that glyph is already in Sponsors. Cycle 326
    adds bright/white micro text dots stranded inside sponsor wordmark panels,
    but only with dense Sponsor neighborhood evidence and zero Number evidence.
    Cycle 330 adds a neutral gray/white logo-emblem crumb seen inside a real
    Dirt Late Model sponsor decal, while requiring dense sponsor-box context
    and zero Number evidence. Cycle 331 adds a 4px mixed red/white/dark sponsor
    hairline/text stroke from an Audi logo panel without loosening the older
    dark-text bucket. Cycle 334 adds a tiny red/dark wordmark-dot family for
    Mobil-style sponsor logo dots, gated away from Numbers and ornamental Paint.
    Cycle 335 adds tiny cool-blue ZEROFORCE-style wordmark crumbs exposed after
    pale false-Number sponsor panels move back to Sponsors. Cycle 397 adds a
    tiny red/dark separator crumb inside TRACKER-style sponsor wordmarks, gated
    by dense Sponsor context and zero Number/Template evidence. Keep this medium
    residual pass panel-anchored and
    red/dark-trim aware so number outlines and small decorative numbers stay
    put. Cycle 398 adds a tiny saturated sponsor-logo crumb family for magenta
    or red logo pieces stranded as Paint inside already-detected sponsor
    panels, with explicit Number/Template exclusion. Cycle 400 adds a one-pixel
    pale/mixed sponsor hairline text stroke from a dense SK Modified sponsor
    stack, separated from the older 2-3px hairline families so tiny livery or
    number trim does not sneak in. Cycle 347 adds the larger
    SK Modified-style white sponsor wordmark
    fragment stranded inside a saturated yellow/magenta sponsor panel; keep it
    geometry- and panel-context gated instead of raising the general residual
    size cap. Cycle 348 adds tiny warm/mixed logo crumbs stranded inside
    bright sponsor art that was partly absorbed by a nearby Number panel; keep
    it sponsor-dilated, color-mix, and geometry gated so normal number fill
    stays put. Cycle 349 adds a compact red sponsor-logo cap left in Paint on a
    dark sponsor stack, requiring internal Sponsor fill and no Number evidence.
    Cycle 402 adds a DLM red/dark logo-interior crumb left behind after the
    surrounding sponsor fragment was already recovered; keep it bbox-Sponsor
    anchored so red body panels and template-adjacent scraps stay Paint.
    Cycle 403 adds a DLM grayscale sponsor-logo interior stroke inside an
    already-detected sponsor badge; keep it horizontal, tiny, fully
    Sponsor-anchored, and away from Number/Template context. Cycle 404 adds a
    compact grayscale sponsor-logo interior fill island for DLM badges that
    connect to broader Paint/background residuals; keep it bbox-Sponsor filled
    and square-ish so true number art remains untouched.
    Cycle 424 adds a tiny green sponsor-wordmark crumb left in Paint inside a
    white/green DLM sponsor mark; keep it dense-Sponsor anchored and away from
    Number/Template context instead of loosening the saturated crumb bucket.
    Cycle 425 adds a long 3px warm/dark sponsor hairline left in Paint inside a
    DLM logo strip; keep it warm/dark, horizontal, and bbox-Sponsor anchored so
    pale trim and livery pinstripes stay out.
    Cycle 426 adds a tiny red sidecar chip on the edge of a DLM sponsor
    nameplate that sits inside Number dilation; require immediate side-band
    Sponsor evidence plus low bbox Number/Template fill so true number trim is
    not pulled into Sponsors.
    Cycle 429 adds the dark-backed grayscale sibling for DLM sponsor-logo
    interior fills where one half of a small logo is already recovered but the
    darker half remains Paint; require dark-ring sponsor context and no
    Number/Template dilation.
    Cycle 430 adds a tiny blue/white vertical sponsor-logo stroke on dark DLM
    sponsor panels, separate from the older blue-panel crumb family so dark
    livery trim and grayscale holes stay out.
    Cycle 433 adds grayscale micro text/logo crumbs from DLM sponsor panels,
    gated by tiny no-color geometry plus dense Sponsor ring/bbox context so
    template blocks, number holes, and remote white trim remain untouched.
    Cycle 434 adds a darker grayscale micro-logo crumb that can sit inside
    Number dilation without touching real Number pixels; require immediate
    Sponsor bbox/ring support plus zero local Number/Template ownership.
    Cycle 446 adds tiny yellow/dark DLM sponsor wordmark crumbs stranded as
    Paint inside Clements/Davis-style sponsor stacks; keep them fully
    Sponsor-anchored with yellow/dark local context and zero Number/Template
    ownership.
    Cycle 448 adds a tiny vertical warm/white DLM sponsor-text sliver from the
    SWEET VICTORY APPAREL stack; require full Sponsor dilation, mixed red/white
    glyph pixels, and zero Number/Template ownership so red livery chips stay
    out.
    Cycle 459 adds a saturated blue 2px sponsor underline/interior strip that
    can connect to Paint/background by final DLM route masks; require immediate
    dense Sponsor ring support and low Paint/Template ring context so livery
    stripes remain Paint.
    Cycle 475 adds a tiny bright red/white sponsor-wordmark crumb on white/red
    DLM sponsor text; require full Sponsor dilation plus side-band sponsor
    support so red body-panel flecks and number holes stay Paint.
    Cycle 476 adds sparse green/dark sponsor-logo edge shards left in Paint
    inside already-detected sponsor panels; require strong Sponsor bbox/ring
    context and zero Number/Template evidence so green number/livery art stays
    out. Cycle 493 adds the even sparser DLM green diagonal-logo edge sibling,
    requiring stronger immediate Sponsor side/bbox support and zero
    Number/Template context so cyan livery/template-adjacent Paint shards stay
    out. Cycle 495 adds mixed-color DLM contingency/sponsor strip crumbs left in
    Paint on lower edge panels, but only when side-band Sponsor support is
    strong and Number/Template ownership is absent. Cycle 497 adds a larger
    blue/white/dark sponsor-logo tail left in Paint on a DLM wordmark; require
    dense Sponsor overlap plus zero Number/Template ownership so blue number
    strips and livery pixels stay editable. Cycle 498 adds tiny top-edge DLM
    contingency-strip crumbs that sit in Number dilation but not actual Number
    pixels; keep them constrained to bright top-edge panel context and tiny
    logo-color anatomy. Cycle 499 adds the horizontal red/green sibling for
    tiny number-panel contingency wordmarks that sit in both Number and Sponsor
    dilation but have zero actual layer ownership; require bright panel context
    plus multicolor logo anatomy so red livery strips stay Paint. Cycle 502
    adds a dark/lime hairline-logo sibling for ultra-thin DLM sponsor text left
    in Paint on yellow/dark sponsor cards; require Sponsor dilation plus
    side-band Sponsor support and zero Number/Template ownership. Cycle 505
    adds blue/dark DLM wordmark crumbs from COMP-style sponsor text: keep the
    branch Sponsor-panel anchored with exact blue/dark geometry siblings so
    blue body stripes, template-adjacent scraps, and number art stay Paint.
    Cycle 506 adds tiny grayscale wordmark-gap crumbs inside already detected
    DLM sponsor wordmarks; keep them unsaturated, Sponsor-dilated, and
    Number/Template-empty so colored livery shards stay Paint.
    Cycle 507 adds paired red/tan logo-gap crumbs from a sponsor-panel mark;
    keep it high-Sponsor-support and low-fill so smooth red livery panels stay
    out. Cycle 508 adds the ultra-flat yellow/dark hairline sibling left in
    Paint inside DLM sponsor-card wordmarks; require Sponsor side-band support
    and zero Number/Template ownership so green template/livery edge strips
    remain Paint. Cycle 517 adds local blue and sparse grayscale wordmark edge
    completion for DLM sponsor panels whose missing letter/underline strokes
    are fused into the Paint/background residual; re-segment within Sponsor
    neighborhoods and keep Number/Template ownership at zero. Cycle 518 adds a
    narrow dark text crumb sibling for DLM sponsor letters that sit in Number
    dilation but have zero actual Number pixels; require Sponsor bbox/ring
    support so true number trim remains editable Numbers. Cycle 520 adds a
    same-wordmark completion sibling for tiny DLM sponsor strokes that are both
    Sponsor- and Number-dilated but have no actual Number ownership, recovering
    partial letters/logo hairlines without broadening isolated livery pickup.
    Cycle 524 adds a larger green/dark DLM wordmark chunk whose surrounding
    letters are already Sponsors but whose own pixels remain Paint; require
    green wordmark anatomy plus local Sponsor box/side/ring support so smooth
    red livery panels stay editable Paint.
    Cycle 525 adds a tiny vertical blue/purple DLM logo stroke from a lower-side
    sponsor stack; keep it dense-Sponsor boxed and actual-Number/Template empty
    so blue livery outlines and already-owned sponsor stripes stay untouched.
    The live route resize can lower saturation on those sponsor-hole pixels, so
    the blue branch keys on stable hue plus Sponsor-mask context.
    Cycle 527 adds a flat red/white contingency-strip fill left as Paint inside
    a lower sponsor row; keep it horizontal, edge-bearing, Sponsor-dilated, and
    actual Number/Template empty so red/orange livery pinstripes stay Paint.
    Cycle 528 adds dense sponsor-context micro-hole completion for tiny neutral
    strokes and saturated red/yellow logo interiors left as Paint after the
    surrounding Sponsor glyph is already owned; require Sponsor bbox/ring
    dominance so number-adjacent trims and livery scratches stay out.
    Cycle 370 adds a saturated green/cool wordmark edge left in Paint inside
    an already-detected sponsor neighborhood; keep it sponsor-anchored and
    away from Numbers so green body art stays editable Paint. Cycle 392 adds
    square-ish white/yellow vertical wordmark holes inside sponsor panels,
    bounded tightly so standalone livery marks and number-panel holes stay out.
    Cycle 393 adds a tiny red/black contingency-logo crumb family for sponsor
    stacks at response and internal mask scales, requiring dense Sponsor-panel
    context and explicit Number/Template exclusion instead of broadening red
    micro-logo handling. Cycle 535 adds a square-ish grayscale logo-letter
    pocket for Coby-style racing badges whose pixels are connected to the
    broader Paint/background residual; re-segment the glyph island inside dense
    Sponsor context and keep actual Number/Template ownership at zero.
    Cycle 537 adds neutral 2-3px sponsor textline gaps left inside dense DLM
    contingency strips, where one neighboring letter can be recovered while
    adjacent mirrored/upside-down glyph strokes stay Paint; keep it flat,
    grayscale, Sponsor-ring dominated, and actual Number/Template empty.
    Cycle 539 adds wide warm/dark sponsor wordmark interior strips left as
    Paint after the brighter wordmark shell is already Sponsor, including
    strips sitting inside the broad Number dilation halo; require same-bbox
    Sponsor support and zero actual Number/Template ownership so body panels
    and livery blocks remain editable Paint.
    Cycle 540 adds 1px neutral vertical sponsor text strokes left in Paint
    inside dense DLM sponsor stacks; tolerate slight Template/Number dilation
    only when actual bbox/ring/local ownership is empty and Sponsor side/ring
    context is dominant, so seams and template edges stay out.
    Cycle 541 adds tiny sparse neutral/yellow outline crumbs embedded in dense
    Sponsor-owned DLM logo shells; keep recovery tied to zero Number/Template
    ownership plus strong Sponsor bbox/ring/side-band support so body paint and
    true number art remain protected. Cycle 561 adds two red/orange DLM logo-gap
    siblings for partially recovered sponsor decals: a 1px vertical sponsor
    edge stroke and a sparse diamond-logo interior gap. Both are constrained to
    sponsor-dominant neighborhoods and keep actual Number/Template ownership
    empty or sponsor-dominant so red number trim stays editable. Cycle 562 adds
    a vertical grayscale DLM wordmark-stroke sibling for small white/dark sponsor
    letter islands left in Paint on colorful sponsor panels, gated away from
    red livery/number edge slivers and template-dominant white body panels.
    Cycle 578 adds a compact red/white local wordmark-gap sibling for DLM
    sponsor letters that sit inside both Sponsor and Number dilation but have
    no actual Number ownership; require square high-fill glyph anatomy so
    vertical number halos and red livery scratches stay editable.
    """
    info = {"status": "skipped", "reason": "disabled"}
    if not _PANEL_TEXT_RESIDUAL_SUPPLEMENT:
        return np.zeros(rgb.shape[:2], np.uint8), info
    if cv2 is None:
        return np.zeros(rgb.shape[:2], np.uint8), {"status": "skipped", "reason": "cv2_unavailable"}

    H, W = rgb.shape[:2]
    numbers_b = numbers > 0
    sponsors_b = sponsors > 0
    template_b = template > 0
    brand_b = brand > 0
    anchor_src = sponsors_b | brand_b
    if not (numbers_b.any() or anchor_src.any()):
        return np.zeros((H, W), np.uint8), {"status": "skipped", "reason": "no_panel_anchor"}

    claimed = numbers_b | sponsors_b | template_b | brand_b
    residual = ~claimed
    hsv = cv2.cvtColor(rgb, cv2.COLOR_RGB2HSV)
    gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
    edges = cv2.Canny(gray, 45, 120)
    hue = hsv[:, :, 0]
    sat = hsv[:, :, 1]
    val = hsv[:, :, 2]

    min_dim = float(max(1, min(H, W)))
    radius = max(6, int(round(_PANEL_TEXT_RESIDUAL_ANCHOR_RADIUS * min_dim)))
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (radius * 2 + 1, radius * 2 + 1))
    sponsor_anchor = cv2.dilate(anchor_src.astype(np.uint8), kernel) > 0
    number_anchor = cv2.dilate(numbers_b.astype(np.uint8), kernel) > 0

    count, labels, stats, _cent = cv2.connectedComponentsWithStats(residual.astype(np.uint8), 8)
    canvas_area = float(max(1, H * W))
    margin = max(4, int(round(0.008 * min_dim)))
    candidates = []

    for i in range(1, count):
        x, y, w, h, area = [int(v) for v in stats[i]]
        touches_border = x <= 1 or y <= 1 or x + w >= W - 1 or y + h >= H - 1
        shell_max_area = max(430, int(round(0.00125 * canvas_area)))
        shell_long_limit = max(60, int(round(0.085 * min_dim)))
        shell_short_limit = max(34, int(round(0.052 * min_dim)))
        sponsor_shell_size = (
            area <= shell_max_area
            and 8 <= min(w, h) <= shell_short_limit
            and max(w, h) <= shell_long_limit
        )
        hairline_text_size = (
            18 <= area <= 70
            and 2 <= min(w, h) <= 3
            and max(w, h) <= max(30, int(round(0.036 * min_dim)))
        )
        scaled_lime_dark_hairline_text_size = (
            hairline_text_size
            or (
                32 <= area <= 130
                and 3 <= min(w, h) <= 6
                and max(w, h) <= max(60, int(round(0.042 * min_dim)))
            )
        )
        single_pixel_hairline_text_size = (
            24 <= area <= 72
            and min(w, h) == 1
            and 24 <= max(w, h) <= max(42, int(round(0.048 * min_dim)))
        )
        long_warm_hairline_text_size = (
            80 <= area <= 130
            and 2 <= h <= 4
            and 56 <= w <= max(82, int(round(0.082 * min_dim)))
        )
        sponsor_warm_dark_wordmark_strip_size = (
            520 <= area <= max(1300, int(round(0.00135 * canvas_area)))
            and 6 <= h <= max(14, int(round(0.014 * min_dim)))
            and 80 <= w <= max(170, int(round(0.170 * min_dim)))
        )
        sponsor_large_white_wordmark_size = (
            950 <= area <= 2400
            and 90 <= w <= 160
            and 12 <= h <= 24
            and 5.0 <= max(w / float(max(1, h)), h / float(max(1, w))) <= 9.5
        )
        sponsor_border_grayscale_wordmark_size = (
            touches_border
            and 900 <= area <= 1800
            and 42 <= w <= 78
            and 18 <= h <= 34
            and 1.45 <= max(w / float(max(1, h)), h / float(max(1, w))) <= 3.35
        )
        red_logo_cap_size = (
            180 <= area <= 430
            and 15 <= min(w, h) <= 30
            and max(w, h) <= 38
        )
        sponsor_blue_white_logo_tail_size = (
            35 <= area <= 70
            and 12 <= min(w, h) <= 24
            and 18 <= max(w, h) <= 34
        )
        if (
            area < 18
            or (
                area > 430
                and not sponsor_shell_size
                and not sponsor_large_white_wordmark_size
                and not sponsor_border_grayscale_wordmark_size
                and not sponsor_warm_dark_wordmark_strip_size
            )
        ):
            continue
        if touches_border:
            border_long_limit = max(56, int(round(0.095 * min_dim)))
            border_short_limit = max(24, int(round(0.052 * min_dim)))
            if max(w, h) > border_long_limit or min(w, h) > border_short_limit or w < 2 or h < 3:
                continue
        elif sponsor_shell_size and area > 430:
            pass
        elif sponsor_large_white_wordmark_size:
            pass
        elif hairline_text_size:
            pass
        elif single_pixel_hairline_text_size:
            pass
        elif long_warm_hairline_text_size:
            pass
        elif sponsor_warm_dark_wordmark_strip_size:
            pass
        elif red_logo_cap_size:
            pass
        elif sponsor_blue_white_logo_tail_size:
            pass
        elif max(w, h) > 52 or min(w, h) > 18 or w < 3 or h < 3:
            continue

        comp = labels == i
        bbox_area = max(1, w * h)
        area_frac = area / canvas_area
        bbox_frac = bbox_area / canvas_area
        fill = area / float(bbox_area)
        bbox_sponsor_fill = float(anchor_src[y:y + h, x:x + w].sum()) / float(bbox_area)
        bbox_number_fill = float(numbers_b[y:y + h, x:x + w].sum()) / float(bbox_area)
        bbox_template_fill = float(template_b[y:y + h, x:x + w].sum()) / float(bbox_area)
        aspect = max(w / float(max(1, h)), h / float(max(1, w)))
        edge_density = float((edges[comp] > 0).mean()) if area else 0.0
        sponsor_overlap = float((comp & sponsor_anchor).sum()) / float(max(1, area))
        number_overlap = float((comp & number_anchor).sum()) / float(max(1, area))
        template_overlap = float((comp & template_b).sum()) / float(max(1, area))

        x0 = max(0, x - margin)
        y0 = max(0, y - margin)
        x1 = min(W, x + w + margin)
        y1 = min(H, y + h + margin)
        local = np.zeros((H, W), bool)
        local[y0:y1, x0:x1] = True
        ring = local.copy()
        ring[y:y + h, x:x + w] = False
        near_sponsor = float((local & anchor_src).sum()) / float(max(1, local.sum()))
        near_number = float((local & numbers_b).sum()) / float(max(1, local.sum()))
        near_template = float((local & template_b).sum()) / float(max(1, local.sum()))
